  await stop(nodes[second]);
  await assert.rejects(engine.begin(['a', 'b']));
  await assert.rejects(partitionedEngine.begin(['a']));
  console.log('PASS real etcd: majority loss refuses a fresh linearizable snapshot');
} finally {
