/// <summary>
/// The <c>clink</c> client mode and the import, export and print helpers of
/// <c>Program.cs</c>, moved here so the entry point stays below the 900-line
/// warning threshold of <c>csharp/scripts/check-file-size.mjs</c> (issue #172).
/// </summary>
internal static class CliIo
{
    internal static readonly Option<string?> InputOption = new("--in", "--lino-input", "--import")
    {
        Description = "Path to read and import a LiNo file into the database"
    };

    internal static readonly Option<int> InputMaxDepthOption = new("--in-max-depth")
    {
        Description = $"LiNo import nesting limit (1 to {LinoDatabaseInput.MaxImportDepth}; default: {LinoDatabaseInput.DefaultImportDepth})",
        DefaultValueFactory = _ => LinoDatabaseInput.DefaultImportDepth,
        CustomParser = result =>
        {
            if (result.Tokens.Count == 1
                && int.TryParse(result.Tokens[0].Value, NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out var depth)
                && depth is >= 1 and <= LinoDatabaseInput.MaxImportDepth)
            {
                return depth;
            }

            result.AddError($"Invalid value for '--in-max-depth': expected an integer from 1 to {LinoDatabaseInput.MaxImportDepth}");
            return LinoDatabaseInput.DefaultImportDepth;
        }
    };

    internal static readonly Option<string?> BinaryInputOption = new("--import-binary", "--binary-input", "--binary-in")
    {
        Description = "Path to read and import a store archive in binary links notation"
    };

    internal static readonly Option<string?> BinaryOutputOption = new("--export-binary", "--binary-output", "--binary-out")
    {
        Description = "Path to write the complete database, names included, as a store archive in binary links notation"
    };

    internal static int RunTransactionBatch(FileTransitionLog journal, TransactionsDecorator transactions,
        VersionControlDecorator? versionControl, Func<int> run)
    {
        // The mapped store may persist a change before the write callback runs.
        // The durable undo image protects it until the batched decision is synced.
        journal.SyncOnAppend = false;
        var before = transactions.LastLoggedSequence;
        using var transaction = versionControl?.BeginTransaction() ?? transactions.BeginTransaction();
        var exitCode = run();
        if (exitCode == 0 && transactions.LastLoggedSequence != before) transaction.Commit();
        return exitCode;
    }

