export const asOperand = (file) => (file.startsWith('/') ? file : `./${file}`);

export function gunzip(buffer) {
  return gunzipSync(buffer, { maxOutputLength: MAX_DECOMPRESSED_BYTES });
}

const field = (block, start, length) =>
