    longName = undefined;
    if (type === 'L') longName = content.toString('utf8').replace(/\0.*$/s, '');
    else if (type === 'x') longName = /(?:^|\n)\d+ path=([^\n]*)\n/.exec(content)?.[1];
    else if (type === '0' || type === '7') entries.push({ name, content });
    offset += 512 + Math.ceil(size / 512) * 512;
