// Repository governance rules of issue #111 that are not the stage gate
// itself (the gate rule lives in workflow-policy.test.mjs): the required
// status checks always report, every suite proves it loaded the golden
// fixtures, no workflow closes or flags pull requests because of age, and a
// red Dependencies check on main is tracked in an issue.
import assert from 'node:assert/strict';
import test from 'node:test';
import { readJobs, workflows } from './workflow-files.mjs';

test('the required stage checks report on every pull request (issue #111)', () => {
  for (const name of ['javascript.yml', 'rust.yml', 'csharp.yml']) {
    const { text } = workflows.find((workflow) => workflow.name === name);
    const on = text.slice(text.indexOf('\non:\n'), text.indexOf('\njobs:\n'));
    assert.match(on, /^ {2}pull_request:/m, `${name} must run on pull requests`);
    assert.doesNotMatch(
      on,
      /^ {4}paths(?:-ignore)?:/m,
      `${name}: a path filter would skip the parity check and leave its required check pending`,
    );
    assert.match(text, /^ {2}pipeline-status:\n {4}name: Pipeline Status \(\w+\)/m);
  }
});

test('read-only concurrency only replaces superseded PR synchronizations (issue #207)', () => {
  const scope =
    "${{ github.event_name == 'pull_request' && github.event.action == 'synchronize' && github.ref || github.event_name == 'push' && github.sha || github.run_id }}";
  const cancel = "${{ github.event_name == 'pull_request' && github.event.action == 'synchronize' }}";
  for (const { name, text } of workflows) {
    const groups = [...text.matchAll(/^ +group: (.*)\n +cancel-in-progress: (.*)$/gm)];
    assert.ok(groups.length, `${name}: missing concurrency groups`);
    const queueCount = [...text.matchAll(/^ +queue\s*:/gm)].length;
    let writerGroups = 0;
    for (const [block, group, policy] of groups) {
      if (group.startsWith('main-writer-')) {
        writerGroups++;
        const nextLine = text.slice(text.indexOf(block) + block.length + 1).split('\n')[0];
        assert.equal(nextLine.trim(), 'queue: max', `${name}: writer lost its queue`);
      }
      if (policy === 'false') continue;
      assert.equal(policy, cancel, `${name}: ${group} cancels unrelated runs`);
      assert.ok(group.includes(scope), `${name}: ${group} can collide across revisions or events`);
    }
    assert.equal(queueCount, writerGroups, `${name}: queue is only supported for shared writers`);
  }
});

