    endpoints.map(async (endpoint) => {
      let failure;
      for (let attempt = 0; attempt < attempts; attempt++) {
        try {
          return await memberStatus(endpoint, fetch);
        } catch (error) {
          failure = error;
          await pause(100);
        }
      }
      throw failure;
    }),
  );
}

