const script=String.raw`#!/usr/bin/env bash
set -euo pipefail
repo=link-foundation/link-cli
logs=dev/log/issues/207/pulls/208/ci-logs
for spec in issues/208/comments pulls/208/comments pulls/208/reviews issues/208/reactions issues/208/timeline; do
  file="$logs/reviews/\$(tr / - <<< "$spec").json"
  gh api "repos/$repo/$spec" --paginate --slurp > "$file.tmp"
  mv "$file.tmp" "$file"
  jq -r --arg spec "$spec" '[.[][]] | [$spec,(length|tostring),([.[]|(.user.login // .actor.login // empty)]|unique|join(","))]|@tsv' "$file"
done
file="$logs/reviews/threads.json"
gh api graphql -f query='query {
