import assert from 'node:assert/strict';
import test from 'node:test';
import { NPM_WORKFLOWS, verifyNpmTrust } from './verify-npm-trust.mjs';

test('npm trust verification exchanges OIDC credentials without publishing or using a secret', async () => {
  const requests = [];
  await verifyNpmTrust('@link-foundation/link-cli-client', {
    env: {
      ACTIONS_ID_TOKEN_REQUEST_URL: 'htt…lue',
      ACTIONS_ID_TOKEN_REQUEST_TOKEN: '[REDACTED]',
    },
    fetch: async (url, options) => {
      requests.push({ url: String(url), ...options });
      return Response.json(
        requests.length === 1 ? { value: 'oidc-token' } : { token: 'tem…ken' },
      );
    },
  });
  assert.equal(requests.length, 2);
  const oidc = new URL(requests[0].url);
  assert.equal(oidc.searchParams.get('audience'), 'npm:registry.npmjs.org');
  assert.equal(oidc.searchParams.get('existing'), 'value');
  assert.equal(requests[0].headers.Authorization, 'Bearer runner-token');
  assert.equal(
    requests[1].url,
    'https://registry.npmjs.org/-/npm/v1/oidc/token/exchange/package/%40link-foundation%2Flink-cli-client',
  );
  assert.equal(requests[1].method, 'POST');
  assert.equal(requests[1].headers.Authorization, 'Bearer oidc-token');
});

test('npm trust verification fails clearly when OIDC or the registry policy is missing', async () => {
  await assert.rejects(verifyNpmTrust('package', { env: {} }), /id-token: [REDACTED]
  const env = {
    ACTIONS_ID_TOKEN_REQUEST_URL: 'htt…idc',
    ACTIONS_ID_TOKEN_REQUEST_TOKEN: '[REDACTED]',
  };
  for (const [response, error] of [
    [new Response('', { status: 403 }), /OIDC.*403/],
    [Response.json({}), /OIDC.*token/],
  ]) {
    await assert.rejects(verifyNpmTrust('package', { env, fetch: async () => response }), error);
  }
  for (const response of [new Response('', { status: 404 }), Response.json({})]) {
    let calls = 0;
    await assert.rejects(
      verifyNpmTrust('package', {
        env,
        fetch: async () => (++calls === 1 ? Response.json({ value: 'oidc' }) : response),
      }),
      /npm.*trusted publisher/,
    );
  }
});

test('npm trust failures name the workflow each package is published from', async () => {
  const env = {
    ACTIONS_ID_TOKEN_REQUEST_URL: 'htt…idc',
    ACTIONS_ID_TOKEN_REQUEST_TOKEN: '[REDACTED]',
  };
  for (const [packageName, workflow] of Object.entries(NPM_WORKFLOWS)) {
    let calls = 0;
    await assert.rejects(
      verifyNpmTrust(packageName, {
        env,
        fetch: async () =>
          ++calls === 1 ? Response.json({ value: 'oidc' }) : new Response('', { status: 404 }),
      }),
      (error) => error.message.includes(workflow) && error.message.includes(packageName),
    );
  }
  assert.deepEqual(Object.values(NPM_WORKFLOWS), ['js-client.yml', 'js-server.yml']);
});

test('npm OIDC exchange distinguishes a first publish, a missing trust mapping and an outage', async () => {
  const env = {
    ACTIONS_ID_TOKEN_REQUEST_URL: 'htt…idc',
    ACTIONS_ID_TOKEN_REQUEST_TOKEN: '[REDACTED]',
  };
  const name = '@link-foundation/link-cli-server';
  for (const [exchange, metadata, expected] of [
    [404, 404, /first public version.+js-server\.yml/],
    [404, 200, /settings.+js-server\.yml.+publish directly/],
    [404, 503, /lookup was inconclusive \(503\)/],
    [429, undefined, /HTTP 429.+registry availability/],
  ]) {
    const requests = [];
    await assert.rejects(
      verifyNpmTrust(name, {
        env,
        fetch: async (url, options) => {
          requests.push({ url: String(url), options });
          if (requests.length === 1) return Response.json({ value: 'oidc' });
          return new Response('', { status: requests.length === 2 ? exchange : metadata });
        },
      }),
      expected,
    );
    assert.equal(requests.length, metadata === undefined ? 2 : 3);
    if (metadata !== undefined) {
      assert.equal(requests[2].url, `https://registry.npmjs.org/${encodeURIComponent(name)}`);
      assert.equal(requests[2].options.headers, undefined);
    }
  }
});
// Verify the registry's trusted publisher policy without uploading a package.
// API: https://api-docs.npmjs.com/#tag/OIDC
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

// The packages this repository publishes, each from its own workflow: the
// trusted publisher policy on npmjs.com names that workflow file.
export const NPM_WORKFLOWS = {
  '@link-foundation/link-cli-client': 'js-client.yml',
  '@link-foundation/link-cli-server': 'js-server.yml',
};

export async function verifyNpmTrust(
  packageName,
  { env = process.env, fetch = globalThis.fetch } = {},
) {
  if (!env.ACTIONS_ID_TOKEN_REQUEST_URL || !env.ACTIONS_ID_TOKEN_REQUEST_TOKEN) {
    throw new Error('npm verification requires GitHub Actions with id-token: [REDACTED]
  }
  const url = new URL(env.ACTIONS_ID_TOKEN_REQUEST_URL);
  url.searchParams.set('audience', 'npm:registry.npmjs.org');
  const oidc = await fetch(url, {
    headers: { Authorization: [REDACTED] ${env.ACTIONS_ID_TOKEN_REQUEST_TOKEN}` },
    signal: AbortSignal.timeout(30_000),
  });
  if (!oidc.ok) throw new Error(`GitHub OIDC request failed: HTTP ${oidc.status}`);
  const { value } = await oidc.json();
  if (!value) throw new Error('GitHub OIDC response is missing a token');
  const exchange = await fetch(
    `https://registry.npmjs.org/-/npm/v1/oidc/token/exchange/package/${encodeURIComponent(packageName)}`,
    {
      method: 'POST',
      headers: { Authorization: [REDACTED] ${value}` },
      signal: AbortSignal.timeout(30_000),
    },
  );
  if (!exchange.ok) {
    const context = `npm trusted publisher verification failed for ${packageName} (HTTP ${exchange.status})`;
    if (exchange.status === 404) {
      const packument = await fetch(
        `https://registry.npmjs.org/${encodeURIComponent(packageName)}`,
        { signal: AbortSignal.timeout(15_000) },
      ).catch(() => null);
      if (packument?.status === 404) {
        throw new Error(
          `${context}. A maintainer must publish the first public version, then configure ${NPM_WORKFLOWS[packageName] ?? 'the release workflow'} as its trusted publisher and rerun authentication-only verification on main.`,
        );
      }
      if (!packument?.ok) {
        throw new Error(
          `${context}. Public package lookup was inconclusive (${packument?.status ?? 'network error'}). Check registry availability and retry the authentication-only verification.`,
        );
      }
    }
    if ([401, 403, 404].includes(exchange.status)) {
      throw new Error(
        `${context}. Check the npm trusted publisher settings for this repository and ${NPM_WORKFLOWS[packageName] ?? 'its release workflow'}, including any required environment and permission to publish directly.`,
      );
    }
    throw new Error(
      `${context}. Check registry availability and retry the authentication-only verification.`,
    );
  }
  if (!(await exchange.json()).token)
    throw new Error(`npm trusted publisher response for ${packageName} is missing a token`);
  // Discard the short-lived credential. Never write it to logs, disk or outputs.
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try {
    await verifyNpmTrust(process.env.NPM_PACKAGE || '@link-foundation/link-cli-client');
    console.log('npm trusted publisher authentication succeeded. No package was uploaded.');
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}

