// Unit tests of the ring kinds (`file`, `mmap`, `shm`, `signal`) against a JS
// listener of the rendezvous directory (test/support/ipc-listener.mjs), and of
// the ring stream's failure paths on in-memory regions. They need no `clink`.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { test } from 'node:test';
import {
  FileRegion,
  MemoryRegion,
  PollNotifier,
  RING_HEADER,
  RingStream,
  SignalNotifier,
  connectRing,
  initialize,
  installSignal,
  peerSignal,
  regionSize,
  ringBase,
  validate,
} from '../src/ipc-ring.js';
import { connectStream, parseEndpoint } from '../src/ipc.js';
import {
  Listener,
  collect,
  deadPid,
  echo,
  payload,
  rejectsWith,
  sleep,
  tempDir,
} from './support/ipc-listener.mjs';

const LINUX = process.platform === 'linux';
const SIGNALS = os.constants.signals;

/** A region that fails every access once `fail` is set. */
class FailingRegion extends MemoryRegion {
  fail = false;

  read(offset, length) {
    if (this.fail) throw new Error('region lost');
    return super.read(offset, length);
  }

  close() {
    if (this.fail) throw new Error('region lost');
  }
}

const side = (region, { client = true, peerPid = process.pid } = {}) =>
  new RingStream({ kind: 'test', region, client, notifier: new PollNotifier(1), peerPid });

const fresh = (capacity = 64, Region = MemoryRegion) => {
  const region = new Region(regionSize(capacity));
  initialize(region, capacity);
  return region;
};

const written = (stream, bytes) =>
  new Promise((resolve, reject) => {
    stream.write(bytes, (error) => (error ? reject(error) : resolve()));
  });

const ended = (stream) =>
  new Promise((resolve, reject) => stream.end((error) => (error ? reject(error) : resolve())));

for (const kind of ['file', 'mmap', 'signal', 'shm']) {
  test(
    `${kind}: connects through the rendezvous and echoes`,
    { skip: kind === 'shm' && !LINUX },
    async (t) => {
      const dir = tempDir(t);
      const listener = new Listener(dir, kind, { onStream: echo });
      t.after(() => listener.close());
      const stream = await connectStream(`${kind}:${dir}?capacity=64&poll=1`);
      assert.equal(stream.kind, kind);
      assert.equal(stream.capacity, 64);
      assert.equal(stream.peerPid, process.pid);
      const sent = payload(5_000);
      const received = collect(stream);
      stream.end(sent);
      assert.deepEqual(await received, sent);
      stream.destroy();
      assert.deepEqual(fs.readdirSync(dir), ['listener.json'], 'the region is removed at once');
    },
  );
}

test('a ring keeps its file until it hangs up on Windows', async (t) => {
  const dir = tempDir(t);
  const listener = new Listener(dir, 'file', { onStream: echo });
  t.after(() => listener.close());
  const stream = await connectRing(parseEndpoint(`file:${dir}`), {}, 'win32');
  assert.equal(fs.readdirSync(dir).filter((name) => name.endsWith('.ring')).length, 1);
  await new Promise((resolve) => stream.destroy().once('close', resolve));
  assert.deepEqual(fs.readdirSync(dir), ['listener.json']);
});

test('a refused ring connection removes its region', async (t) => {
  const dir = tempDir(t);
  let answer = () => ({ error: 'no room' });
  const listener = new Listener(dir, 'signal', { answer: () => answer() });
  t.after(() => listener.close());
  await assert.rejects(connectStream(`signal:${dir}`), rejectsWith('ECONNREFUSED', /no room/));
  answer = () => ({ pid: process.pid });
  await assert.rejects(connectStream(`signal:${dir}`), rejectsWith('EINVAL', /lacks the number/));
  assert.deepEqual(fs.readdirSync(dir), ['listener.json']);
});

test('a ring region that cannot be sized is removed', async (t) => {
  const dir = tempDir(t);
  const listener = new Listener(dir, 'mmap');
  t.after(() => listener.close());
  t.mock.method(fs, 'ftruncateSync', () => {
    throw Object.assign(new Error('disk full'), { code: 'ENOSPC' });
  });
  await assert.rejects(connectStream(`mmap:${dir}`), /disk full/);
  assert.deepEqual(fs.readdirSync(dir), ['listener.json']);
});

test('ring handshakes check the signal numbers', () => {
  assert.equal(peerSignal({ signal: 10 }), 10);
  assert.throws(() => peerSignal({}), rejectsWith('EINVAL', /lacks/));
  for (const signal of [0, 65]) {
    assert.throws(() => peerSignal({ signal }), rejectsWith('EINVAL', /invalid signal/));
  }
  for (const signo of [999, SIGNALS.SIGKILL, SIGNALS.SIGSTOP]) {
    assert.throws(() => installSignal(signo), rejectsWith('EINVAL', /cannot be caught/));
  }
});

test('the signal ring takes the report signal over', (t) => {
  const report = process.report;
  const saved = [report.signal, report.reportOnSignal];
  t.after(() => {
    report.signal = saved[0];
    report.reportOnSignal = saved[1];
  });
  report.signal = 'SIGWINCH';
  report.reportOnSignal = true;
  installSignal(SIGNALS.SIGWINCH);
  assert.equal(report.reportOnSignal, false);
  // Installed once for the life of the process.
  report.reportOnSignal = true;
  installSignal(SIGNALS.SIGWINCH);
  assert.equal(report.reportOnSignal, true);
});

test('a signal the process cannot handle is reported', (t) => {
  t.mock.method(process, 'on', () => {
    throw new Error('uv_signal_start EINVAL');
  });
  assert.throws(() => installSignal(SIGNALS.SIGURG), rejectsWith('EINVAL', /cannot be caught/));
});

test('the signal notifier waits for a signal or its limit', async () => {
  const gone = new SignalNotifier(deadPid(), SIGNALS.SIGWINCH);
  gone.notify();
  const own = new SignalNotifier(process.pid, SIGNALS.SIGWINCH);
  const generation = own.generation();
  await own.wait(generation, 0, 1000);
  const started = Date.now();
  await own.wait(generation, 16, 20);
  assert.ok(Date.now() - started >= 15);
  const woken = own.wait(generation, 16, 10_000);
  own.notify();
  await woken;
  assert.notEqual(own.generation(), generation);
  await own.wait(generation, 16, 10_000);
});

test('ring regions are checked before use', (t) => {
// The two byte rings of `shm`, `mmap`, `file` and `signal` (the "Ring region"
// section of docs/protocol/ipc-transports-v1.md; the reference is
// rust/src/protocol/ipc/ring.rs). Node.js has no shared mappings, so the
// region is accessed with positioned reads and writes of the file that backs
// it; the counter complements make that safe against concurrent stores.

import fs from 'node:fs';
import os from 'node:os';
import { Duplex } from 'node:stream';
import { brokenPipe, hungUp, IpcError, outgoingClosed } from './ipc-endpoint.js';
import { numberField, PeerWatch, Rendezvous } from './ipc-rendezvous.js';
import { trace } from './ipc-trace.js';

export const MAGIC = Buffer.from('LIPC', 'latin1');
export const VERSION = 1;
export const HEADER = 64;
export const RING_HEADER = 128;
const HEAD = 0;
const WRITER_STATE = 8;
const TAIL = 64;
const READER_STATE = 72;
const OPEN = 0;
const ENDED = 1;
const ABORTED = 2;
const GONE = 2;
const PEER_CHECK = 100;
const READ_CHUNK = 65536;

export const regionSize = (capacity) => HEADER + 2 * (RING_HEADER + capacity);
export const ringBase = (ring, capacity) => HEADER + ring * (RING_HEADER + capacity);

const immediate = () => new Promise((resolve) => setImmediate(resolve));
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/** A region of bytes both processes see: any object with `read` and `write` at offsets. */
export class FileRegion {
  constructor(fd, length) {
    this.fd = fd;
    this.length = length;
  }

  read(offset, length) {
    const buffer = Buffer.alloc(length);
    let done = 0;
    while (done < length) {
      const count = fs.readSync(this.fd, buffer, done, length - done, offset + done);
      if (count === 0) throw new IpcError('the ring region is too small', 'EINVAL');
      done += count;
    }
    return buffer;
  }

  write(offset, bytes) {
    let done = 0;
    while (done < bytes.length) {
      done += fs.writeSync(this.fd, bytes, done, bytes.length - done, offset + done);
    }
  }

  close() {
    fs.closeSync(this.fd);
  }
}

/** An in-memory region, for tests of the ring itself. */
export class MemoryRegion {
  constructor(length) {
    this.bytes = Buffer.alloc(length);
    this.length = length;
  }

  read(offset, length) {
    return Buffer.from(this.bytes.subarray(offset, offset + length));
  }

  write(offset, bytes) {
    bytes.copy(this.bytes, offset);
  }

  close() {}
}

const load = (region, offset) => region.read(offset, 4).readUInt32LE(0);

const store = (region, offset, value) => {
  const bytes = Buffer.alloc(4);
  bytes.writeUInt32LE(value >>> 0, 0);
  region.write(offset, bytes);
};

/** Writes the header of a fresh, zero-filled region. */
export function initialize(region, capacity) {
  region.write(0, MAGIC);
  store(region, 4, VERSION);
  store(region, 8, capacity);
  for (const ring of [0, 1]) {
    const base = ringBase(ring, capacity);
    store(region, base + HEAD + 4, 0xffffffff);
    store(region, base + TAIL + 4, 0xffffffff);
  }
}

/** Checks the header and returns the capacity. */
export function validate(region) {
  const fail = (message) => new IpcError(message, 'EINVAL');
  if (region.length < HEADER) throw fail('the ring region is too small');
  if (!region.read(0, 4).equals(MAGIC)) throw fail('the ring region lacks the `LIPC` magic');
  if (load(region, 4) !== VERSION) throw fail('the ring region has another version');
  const capacity = load(region, 8);
  if (capacity < 64 || capacity > 1 << 30 || regionSize(capacity) > region.length) {
    throw fail('the ring region has an invalid capacity');
  }
  return capacity;
}

/** A counter whose complement matches, read again while torn. */
function counter(region, offset) {
  for (let attempt = 0; attempt <= 1_000_000; attempt += 1) {
    const bytes = region.read(offset, 8);
    const value = bytes.readUInt32LE(0);
    if (value === ~bytes.readUInt32LE(4) >>> 0) return value;
  }
  throw new IpcError('a ring counter stays torn', 'EINVAL');
}

/** Stores a counter: the value first, the complement second. */
function publish(region, offset, value) {
  store(region, offset, value);
  store(region, offset + 4, ~value >>> 0);
}

/** `[head, tail]` of a ring, consistent with each other. */
function positions(region, base, capacity) {
  for (;;) {
    const head = counter(region, base + HEAD);
      callback();
    } catch (error) {
      callback(error);
    }
  }

  _destroy(error, callback) {
    if (!this.#released) {
      this.#released = true;
      trace(`${this.kind} ring to process ${this.peerPid} hung up`);
      try {
        if (load(this.#region, this.#outgoing + WRITER_STATE) === OPEN) {
          store(this.#region, this.#outgoing + WRITER_STATE, ENDED);
        }
        store(this.#region, this.#incoming + READER_STATE, GONE);
        this.#notifier.notify();
      } catch {
        // The region is unusable; the peer's liveness check notices.
      }
      try {
        this.#region.close();
      } catch {
        // Already closed.
      }
      for (const file of this.#cleanup) fs.rmSync(file, { force: true });
    }
    callback(error);
  }
}

const SUFFIX = { mmap: 'mmap', file: 'ring', signal: 'sig' };

function createFile(file, size) {
  const { O_RDWR, O_CREAT, O_EXCL } = fs.constants;
  const fd = fs.openSync(file, O_RDWR | O_CREAT | O_EXCL, 0o600);
  try {
    fs.ftruncateSync(fd, size);
  } catch (error) {
    fs.closeSync(fd);
    fs.rmSync(file, { force: true });
    throw error;
  }
  return fd;
}

/**
 * Connects to a `shm`, `mmap`, `file` or `signal` listener; `platform`
 * (default: this one) decides when the files are removed.
 */
export async function connectRing(endpoint, { signal } = {}, platform = process.platform) {
  const kind = endpoint.kind;
  const rendezvous = Rendezvous.begin(endpoint, kind);
  const capacity = endpoint.number('capacity', 65536, 64, 1 << 30);
  const size = regionSize(capacity);
  // `shm` is the POSIX object `/lcID`, which Linux keeps in /dev/shm.
  const file = kind === 'shm' ? `/dev/shm/lc${rendezvous.id}` : rendezvous.path(SUFFIX[kind]);
  const region = new FileRegion(createFile(file, size), size);
  const forget = () => fs.rmSync(file, { force: true });
  try {
    initialize(region, capacity);
    const poll = endpoint.millis('poll', 5);
    let fields = {};
    if (kind === 'signal') {
      const own = endpoint.number('signo', os.constants.signals.SIGUSR2, 1, 64);
      installSignal(own);
      fields = { signal: own };
    }
    const ack = await rendezvous.request(fields, signal);
    const peer = rendezvous.peerOf(ack);
    const notifier =
      kind === 'signal' ? new SignalNotifier(peer, peerSignal(ack)) : new PollNotifier(poll);
    // Both sides hold the region open now; nothing should outlive a crash.
    const windows = platform === 'win32';
    const cleanup = windows ? [file] : [];
    if (!windows) forget();
    const stream = new RingStream({ kind, region, notifier, peerPid: peer, cleanup });
    trace(`${kind} connected as ${rendezvous.id} to process ${peer}, ${capacity} bytes per ring`);
    return stream;
  } catch (error) {
    region.close();
    forget();
    throw error;
  }
