/**
 * The links protocol over an IPC stream: a {@link TcpTransport} (pipelining,
 * pushes, limits) whose capabilities name the endpoint kind.
 */
export class IpcTransport extends TcpTransport {
  #stream;
  #onEnd;

  /** Wraps a connected duplex stream; `owned: false` leaves it open on close. */
  constructor(stream, options = {}) {
    const { kind = 'ipc', endpoint, owned = true } = options;
    super(stream, {
      ...options,
      capabilities: { transport: kind, rawTcp: kind === 'tcp', ...options.capabilities },
    });
    this.kind = kind;
    this.endpoint = endpoint;
    this.#stream = stream;
    // The streams allow half-open connections: the server ending its side
    // ends this one too (or, for a stream left open, just this transport).
    this.#onEnd = () => {
      if (owned) stream.end();
      else this.onClose();
    };
    stream.on('end', this.#onEnd);
  }

  /**
   * Connects to `endpoint` (also a TCP `{ host, port }`), honouring `signal`,
   * `deadline` and `timeout`.
   */
  static async connect(endpoint, options = {}) {
    const parsed = parseEndpoint(fromAddress(endpoint));
    let stream;
    try {
      stream = await connectStream(parsed, options);
    } catch (error) {
      if (error instanceof LinksError) throw error;
      throw new ConnectionClosedError(`cannot connect to ${parsed}: ${error.message}`, {
        outcome: 'not-sent',
        cause: error,
      });
    }
    return new IpcTransport(stream, {
      ...options,
      owned: true,
      kind: parsed.kind,
      endpoint: parsed.toString(),
    });
  }

  async close() {
    try {
      await super.close();
    } finally {
      this.#stream.off('end', this.#onEnd);
    }
  }

  destroy() {
    this.#stream.off('end', this.#onEnd);
    super.destroy();
  }

The Node.js client connects natively to `tcp`, `udp`, `unix` (POSIX), `pipe`
(both meanings), `fifo`, `exec`, `file`, `mmap`, `signal` (POSIX) and `shm`
(Linux, through `/dev/shm`). It uses positioned reads/writes for ring regions,
which the complemented counters make safe, and `process.kill` / a `SIGUSR2`
listener for `signal`. Node.js has no API for POSIX or System V message
queues, mailslots, windows messages, ALPC, POSIX shared memory outside Linux,
Windows named events or Windows Unix sockets; for those kinds it starts
`clink --serve stdio --forward ENDPOINT` (the `clink` command is configurable)
and talks to it over anonymous pipes, which still selects exactly the
requested mechanism between the bridge and the server.

