          persist-credentials: false

      - name: Setup .NET
        uses: actions/setup-dotnet@v6
        with:
          dotnet-version: '10.0.403' # Exact version uses the public builds feed; channel redirect returns HTTP 409.

      - name: Restore dependencies
        run: dotnet restore

      - name: Build
        run: dotnet build --no-restore --configuration Release

      # GoldenFixturesTests writes the receipt that a later step checks, so
      # a filtered or skipped golden fixture test fails CI (issue #111).
      - name: Run tests
        env:
          GOLDEN_FIXTURES_RECEIPT: ${{ runner.temp }}/golden-csharp.json
        run: dotnet test --no-build --configuration Release --verbosity normal --collect:"XPlat Code Coverage;Format=json,cobertura"

      - name: Verify every compiled causal branch
        working-directory: .
        shell: bash
        run: |
          reports=(csharp/Foundation.Data.Doublets.Cli.Tests/TestResults/*/coverage.json)
          test "${#reports[@]}" -eq 1
          test -f "${reports[0]}"
          python3 experiments/issue-138/check-causal-raw-coverage.py "${reports[0]}" --require-session
          python3 experiments/issue-138/check-author-fence-coverage.py "${reports[0]}"

      - name: Build remaining examples
        working-directory: .
        run: |
          dotnet build examples/engine-csharp --configuration Release
          dotnet build examples/group-commit-csharp --configuration Release
          dotnet build examples/transaction-names-csharp --configuration Release

