public partial class TransactionsDecorator<TLinkAddress> where TLinkAddress : IUnsignedNumber<TLinkAddress>
{
    private bool _versionReplay;
    private Action? _versionReplayRecovery;

    internal void RetainVersionReplayRecovery(Action recovery)
    {
        lock (_lock)
        {
            RequireVersionReplayLocked();
            _versionReplayRecovery = recovery;
        }
    }

    internal void ResumeVersionReplayRecovery()
    {
        // Only failed constructors register callbacks: their owner cannot be
        // reached by another caller, so this lock cannot invert a live facade.
        lock (_lock) { _versionReplayRecovery?.Invoke(); }
    }

    private void EnsureNoVersionReplayLocked()
    {
        if (_versionReplay)
            throw new InvalidOperationException("Complete version movement before accessing transaction writes or persistence.");
    }

    internal void BeginVersionReplay()
    {
        lock (_lock)
        {
            EnsureRecoveryCompleteLocked();
            if (_current is not null)
                throw new InvalidOperationException("A transaction still owns the data store.");
            _versionReplay = true;
            // Inline writes already contain every committed effect. Establish
            // their applied markers before movement changes those rows. Queued
            // checkpoints subsequently observe these markers and need no redo.
            _flushData();
            foreach (var transition in _log)
                if (_committed.Contains(transition.TransactionId)) MarkApplied(transition);
            _flushLog();
        }
    }

    internal void ReplayVersionTransition(JournalRecord<TLinkAddress> transition, bool undo)
    {
        lock (_lock)
        {
            RequireVersionReplayLocked();
            if (undo) TryRevertRecord(transition);
            else TryApplyRecord(transition);
        }
    }

    internal void FlushVersionReplay()
    {
        lock (_lock)
        {
            RequireVersionReplayLocked();
            _flushData();
            _flushLog();
        }
    }

    internal void FinishVersionReplay()
    {
        lock (_lock) { _versionReplay = false; _versionReplayRecovery = null; }
    }

    private void RequireVersionReplayLocked()
    {
        if (!_versionReplay) throw new InvalidOperationException("Version movement does not own replay.");
    }
}
    public virtual TLinkAddress SetName(TLinkAddress link, string name)
    {
        lock (_lock)
        {
            return WriteNameLocked(link, name);
        }
    }
    public virtual TLinkAddress GetByName(string name) => _inner.GetByName(name);
    public virtual void RemoveName(TLinkAddress link)
    {
        lock (_lock)
        {
            WriteNameLocked(link, null);
        }
    }

    // Disposal --------------------------------------------------------------

    /// <summary>
    /// Stops the background worker. The wrapped data store and log store
    /// are not disposed here; callers are expected to own those.
    /// </summary>
    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    /// <summary>
    /// Stops the background worker. Derived decorators that own extra
    /// resources override this and call <c>base.Dispose(disposing)</c>.
    /// </summary>
    protected virtual void Dispose(bool disposing)
    {
        if (disposing)
        {
            Shutdown();
        }
    }

    /// <summary>
    /// Stops and joins the background worker before borrowed stores may close.
    /// Concurrent callers all wait for completion. Queued checkpoint work may
    /// be cancelled; committed journal records remain recoverable on reopen.
    /// Callers must finish foreground operations first and callbacks must return.
    /// </summary>
    /// <exception cref="InvalidOperationException">
    /// Called from active background work or while holding the storage lock.
    /// Such a caller cannot wait for worker completion without risking deadlock.
    /// </exception>
    public virtual void Shutdown()
    {
        // Check before the shutdown mutex: an external caller may already hold
        // it while waiting for this callback (or its Task.Run descendant).
        var work = _backgroundWork.Value;
        if ((work is not null && Volatile.Read(ref work.Active) != 0) || Monitor.IsEntered(_lock))
        {
            throw new InvalidOperationException("Shutdown must run outside active storage callbacks.");
        }
        lock (_shutdownLock)
        {
            if (_disposed) return;
            lock (_lock) { EnsureNoVersionReplayLocked(); }
            _asyncQueue.Writer.TryComplete();
